//! Parity binary: loads common ψ₀ fixture (generated by numpy), runs 200 steps.
//! Outputs JSON with max|Δρ|, max|ΔE|, argmax, etc.

use fluid_stratos::{GpeParams, GpeSolver};
use num_complex::Complex;
use std::fs;
use serde::Deserialize;

#[derive(Deserialize)]
struct Psi0Fixture {
    re: Vec<Vec<f64>>,
    im: Vec<Vec<f64>>,
    grid_size: usize,
    domain_size: f64,
}

fn genome_positions(n: usize) -> Vec<(f64, f64)> {
    let center = n as f64 / 2.0;
    let radius = n as f64 / 4.0;
    let mut pos = vec![(center, center)];
    for k in 0..6 {
        let a = 2.0 * std::f64::consts::PI * k as f64 / 6.0;
        pos.push((
            center + radius * 0.5 * a.cos(),
            center + radius * 0.5 * a.sin(),
        ));
    }
    for k in 0..9 {
        let a = 2.0 * std::f64::consts::PI * k as f64 / 9.0;
        pos.push((center + radius * a.cos(), center + radius * a.sin()));
    }
    pos
}

fn mode_energies(psi: &[Vec<Complex<f64>>], params: &GpeParams) -> Vec<f64> {
    let n = params.grid_size;
    let positions = genome_positions(n);
    let mut out = Vec::with_capacity(16);
    for (px, py) in positions.iter().take(16) {
        let mut e = 0.0;
        for (i, row) in psi.iter().enumerate().take(n) {
            for (j, val) in row.iter().enumerate().take(n) {
                let d = ((i as f64 - px).powi(2) + (j as f64 - py).powi(2)).sqrt();
                if d < 5.0 {
                    let weight = (-(d * d) / (2.0 * 9.0)).exp();
                    e += val.norm_sqr() * weight;
                }
            }
        }
        out.push(e);
    }
    out
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let params = GpeParams {
        grid_size: 32,
        domain_size: 10.0,
        dt: 0.005,
        interaction: -1.0,
        trap_frequency: 0.1,
        damping: 0.002,
        hbar: 1.0,
        mass: 1.0,
    };

    let mut solver = GpeSolver::new(params);
    let n = solver.params.grid_size;

    // Load common ψ₀ from numpy-generated fixture
    let fixture_path = "tests/fixtures/psi0.json";
    let fixture_json = fs::read_to_string(fixture_path)?;
    let fixture: Psi0Fixture = serde_json::from_str(&fixture_json)?;

    // Verify fixture matches our parameters
    assert_eq!(fixture.grid_size, n);
    assert!((fixture.domain_size - solver.params.domain_size).abs() < 1e-12);

    // Initialize solver.psi from fixture (note: solver.psi is [row][col] = [y][x])
    for j in 0..n {
        for i in 0..n {
            solver.psi[j][i] = Complex::new(fixture.re[j][i], fixture.im[j][i]);
        }
    }

    // Verify normalization (should already be normalized from numpy)
    // Trust the fixture normalization (do not re-normalize to avoid numerical drift)
    // The fixture was already normalized by numpy to 1.0

    // Save initial density field (element-wise |ψ|²)
    let e0 = mode_energies(&solver.psi, &solver.params);
    let rho0: Vec<f64> = solver
        .psi
        .iter()
        .flatten()
        .map(|v| v.norm_sqr())
        .collect();

    // Run 200 steps
    for _ in 0..200 {
        solver.step();
    }

    let e1 = mode_energies(&solver.psi, &solver.params);
    let rho1: Vec<f64> = solver
        .psi
        .iter()
        .flatten()
        .map(|v| v.norm_sqr())
        .collect();

    let max_delta_density = rho0
        .iter()
        .zip(rho1.iter())
        .map(|(a, b)| (a - b).abs())
        .fold(0.0, f64::max);
    let max_delta_mode_energy = e0
        .iter()
        .zip(e1.iter())
        .map(|(a, b)| (a - b).abs())
        .fold(0.0, f64::max);
    let argmax_initial = e0
        .iter()
        .enumerate()
        .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
        .map(|(i, _)| i)
        .unwrap();
    let argmax_final = e1
        .iter()
        .enumerate()
        .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
        .map(|(i, _)| i)
        .unwrap();

    let out = serde_json::json!({
        "max_delta_density": max_delta_density,
        "max_delta_mode_energy": max_delta_mode_energy,
        "argmax_initial": argmax_initial,
        "argmax_final": argmax_final,
        "mode_energy_initial": e0,
        "mode_energy_final": e1,
    });

    println!("{}", serde_json::to_string_pretty(&out)?);
    Ok(())
}
